import { logger } from '../utils/logger';

let _isBrowser: boolean | undefined;
let _document: Document | null = null;

const getEnvironment = () => {
  if (_isBrowser === undefined) {
    try {
      _isBrowser = typeof window !== 'undefined' && Boolean(window.document);
    } catch {
      _isBrowser = false;
    }
  }
  return _isBrowser ? 'browser' : 'server';
};

const isBrowser = () => getEnvironment() === 'browser';

const getDocument = () => {
  if (!isBrowser()) return null;
  if (_document) return _document;

  try {
    _document = window.document;
    return _document;
  } catch {
    return null;
  }
};

export interface PointerConfig {
  projectId: string;
}

declare global {
  interface Window {
    Pointer?: {
      init: (config: PointerConfig) => void;
    };
    POINTER_INIT: (config: PointerConfig, container: HTMLElement) => void;
  }
}

const doc = getDocument() as Document;
if (!doc) {
  logger.debug('Pointer: Document not available, skipping initialization');
  throw new Error('Pointer: Document not available');
}
const scriptSrcString = doc.currentScript!.getAttribute('src')!;
const scriptSrc = scriptSrcString.startsWith('http')
  ? new URL(scriptSrcString)
  : new URL(scriptSrcString, doc.baseURI);
const apiKey = scriptSrc.searchParams.get('apiKey');
const projectId = scriptSrc.searchParams.get('projectId');

const verifyReact = () => 'React' in window;
const verifyReactDOM = () => 'ReactDOM' in window;
const verifyReady = () => verifyReact() && verifyReactDOM();

const loadScriptAndRun = (src: string, callback: () => void) => {
  const script = document.createElement('script');
  script.src = src;
  script.async = true;
  script.onload = callback;
  document.head.appendChild(script);
};

async function init() {
  try {
    if (typeof window === 'undefined') {
      logger.debug('Pointer: Skipping initialization in SSR environment');
      return;
    }

    if (!verifyReady()) {
      await new Promise(resolve => {
        const maxPolls = 10;
        let pollCount = 0;
        let verified = false;

        const interval = setInterval(() => {
          if (pollCount >= maxPolls) {
            clearInterval(interval);
          }
          if (verifyReady()) {
            verified = true;
            clearInterval(interval);
            resolve(true);
            logger.debug('Pointer: React and ReactDOM found, initializing');
          }
          pollCount++;
        }, 100);

        if (!verified) {
          logger.debug('Pointer: React and ReactDOM not found, importing manually');

          loadScriptAndRun('https://unpkg.com/react@18/umd/react.production.min.js', () => {
            loadScriptAndRun(
              'https://unpkg.com/react-dom@18/umd/react-dom.production.min.js',
              () => {
                resolve(true);
              },
            );
          });
        }
      });
    }

    if (!apiKey && !projectId) {
      logger.error('Pointer: Neither apiKey nor projectId provided');
      return;
    }

    // Create container for Pointer if it doesn't exist
    let container = doc.getElementById('pointer-root');
    if (!container) {
      container = doc.createElement('div');
      container.id = 'pointer-root';
      // Set styles that don't affect children positioning
      Object.assign(container.style, {
        position: 'fixed',
        zIndex: '2147483647',
        inset: '0',
        // Ensure container doesn't affect child positioning
        height: '100%',
        width: '100%',
        overflow: 'hidden',
      });

      const onReady = () => {
        doc.body.appendChild(container!);
        const scriptSrcPath = scriptSrcString.slice(0, scriptSrcString.lastIndexOf('/'));
        const peerScriptSrc = `${scriptSrcPath}/pointer.browser-peer.js`;
        loadScriptAndRun(new URL(peerScriptSrc, scriptSrc.origin).href, () => {
          window.POINTER_INIT(
            {
              projectId: projectId ?? '',
            },
            container!,
          );
        });
      };

      if (doc.readyState === 'complete') onReady();
      else {
        window.addEventListener('load', onReady);
      }
    }
  } catch (error) {
    logger.error('🚨 Pointer: Error initializing', error);
  }
}

init();
