// Logger utility to control console output based on environment variables

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

// Extend Window interface
declare global {
  interface Window {
    POINTER_DEBUG?: boolean;
    POINTER_LOG_LEVEL?: LogLevel;
  }
}

class Logger {
  private static instance: Logger;
  private isEnabled: boolean;
  private logLevel: LogLevel;

  private constructor() {
    // Check both browser and Node.js environment variables
    const debugEnabled =
      typeof process !== 'undefined'
        ? process.env.POINTER_DEBUG === 'true'
        : typeof window !== 'undefined'
          ? window.POINTER_DEBUG === true
          : false;

    const logLevel =
      typeof process !== 'undefined'
        ? (process.env.POINTER_LOG_LEVEL as LogLevel)
        : typeof window !== 'undefined'
          ? window.POINTER_LOG_LEVEL || 'error'
          : 'error';

    this.isEnabled = debugEnabled;
    this.logLevel = this.isValidLogLevel(logLevel) ? logLevel : 'error';
  }

  private isValidLogLevel(level: string): level is LogLevel {
    return ['debug', 'info', 'warn', 'error'].includes(level);
  }

  private shouldLog(level: LogLevel): boolean {
    if (!this.isEnabled) return level === 'error';
    const levels: Record<LogLevel, number> = {
      debug: 0,
      info: 1,
      warn: 2,
      error: 3,
    };
    return levels[level] >= levels[this.logLevel];
  }

  public static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger();
    }
    return Logger.instance;
  }

  public debug(...args: unknown[]): void {
    if (this.shouldLog('debug')) {
      console.debug('🎯', ...args);
    }
  }

  public info(...args: unknown[]): void {
    if (this.shouldLog('info')) {
      console.log('🎯', ...args);
    }
  }

  public warn(...args: unknown[]): void {
    if (this.shouldLog('warn')) {
      console.warn('🎯', ...args);
    }
  }

  public error(...args: unknown[]): void {
    if (this.shouldLog('error')) {
      console.error('🎯', ...args);
    }
  }
}

// Export a singleton instance
export const logger = Logger.getInstance();

// Export type for external use
export type { LogLevel };
